import {
  clearWidgetState,
  getWidgetState,
  setWidgetState
} from "../../../../utils/state-persistance";
import { forEach } from "lodash-es";
const saveTableState = (name, storage, stateToSave) => {
  setWidgetState(
    {
      name,
      type: "table",
      storage
    },
    stateToSave
  );
};
const getTableState = (name, storage) => {
  const state = getWidgetState({
    name,
    type: "table",
    storage
  });
  return state;
};
const clearTableState = (name, storage) => {
  clearWidgetState({
    name,
    storage,
    type: "table"
  });
};
const convertFilterArrayToObject = (filterArray, defaultLogicalOp = "AND") => {
  const filterObject = {};
  forEach(filterArray, (filter) => {
    if (filter.field) {
      filterObject[filter.field] = {
        value: filter.value,
        logicalOp: defaultLogicalOp,
        matchMode: filter.matchMode || "anywhereignorecase",
        type: filter.type
      };
    }
  });
  return filterObject;
};
const convertFilterObjectToArray = (filterObject) => {
  const filterArray = [];
  forEach(filterObject, (filter, field) => {
    filterArray.push({
      field,
      value: filter.value,
      matchMode: filter.matchMode || "anywhereignorecase",
      type: filter.type || "string"
    });
  });
  return filterArray;
};
export {
  clearTableState,
  convertFilterArrayToObject,
  convertFilterObjectToArray,
  getTableState,
  saveTableState
};
